   "body": "# 生物化学\n\n## 课程概述\n在分子层面理解生命：蛋白质、核酸、糖与脂的结构功能，以及代谢的化学逻辑。\n\n## 主要内容\n- 蛋白质结构与功能、酶动力学\n- 核酸结构、糖与脂类\n- 代谢：糖酵解、三羧酸循环、氧化磷酸化、光合磷酸化\n- 代谢调控与信号转导初步\n\n## 先修与后续\n通向 [[c-molecular-bio]]、[[c-microbiology]] 与研究方向 [[r-biomolecules]]。",
