   "fixed": false,
   "body": "# 细胞生物学\n\n## 课程概述\n研究生命的基本单位：细胞器的结构与协作、物质运输、信号转导与细胞周期。\n\n## 主要内容\n- 细胞膜与跨膜运输、内膜系统\n- 线粒体与能量转换、细胞骨架\n- 细胞信号转导、细胞周期与凋亡\n- 细胞连接与细胞外基质\n\n## 先修与后续\n通向 [[c-dev-bio]]、[[c-physiology]] 与 [[r-subcellular]]、[[r-cell-behavior]]。",
