   "body": "# 发育生物学\n\n## 课程概述\n研究受精卵如何建成复杂的生物体：细胞命运决定、图式形成与形态发生。\n\n## 主要内容\n- 受精与早期胚胎发育、细胞命运与分化\n- 图式形成与体轴建立、形态发生素\n- 器官发生、干细胞与再生\n- 演化发育生物学（Evo-Devo）初步\n\n## 先修与后续\n通向 [[r-cell-behavior]] 与 [[r-tissues-organs]]。",
