   "body": "# 生态学\n\n## 课程概述\n研究生物与环境的关系：个体、种群、群落与生态系统四个组织层次。\n\n## 主要内容\n- 种群生态（增长模型、种间关系）\n- 群落结构与演替、生物多样性\n- 生态系统物质循环与能量流动\n- 全球变化生态学与保护生物学\n\n## 先修与后续\n通向 [[r-pop-evolution]]；与地球科学（[[r-atmos]]、[[r-ocean]]）在碳循环上交汇。",
