   "body": "# 遗传学\n\n## 课程概述\n研究遗传与变异的规律：从孟德尔定律到基因组时代的连锁分析与群体遗传。\n\n## 主要内容\n- 孟德尔遗传与连锁互换、染色体遗传\n- 基因突变与 DNA 多态性\n- 数量遗传与群体遗传初步\n- 表观遗传学\n\n## 先修与后续\n通向 [[c-dev-bio]] 与 [[r-genomics]]、[[r-pop-evolution]]。",
