   "fixed": false,
   "body": "# 微生物学\n\n## 课程概述\n研究细菌、古菌、真菌与病毒：微生物的生理、遗传、生态与应用。\n\n## 主要内容\n- 微生物的形态结构与分类鉴定\n- 微生物生长与代谢的多样性\n- 病毒学基础、微生物遗传\n- 微生物生态与工业/医学微生物\n\n## 先修与后续\n通向 [[r-cell-behavior]]（宿主-病原体互作）与合成生物学 [[r-synthetic-bio]] 的底盘细胞工程。",
