   "body": "# 分子生物学\n\n## 课程概述\n研究遗传信息的存储、复制与表达：中心法则是其纲领。\n\n## 主要内容\n- DNA 复制、修复与重组\n- 转录与转录调控（操纵子、表观遗传）\n- 翻译与翻译后加工\n- 基因工程基本技术（克隆、PCR、测序原理）\n\n## 先修与后续\n通向 [[c-genetics]]、[[c-bioinfo]] 与 [[r-genomics]]、[[r-synthetic-bio]]。",
