   "body": "# 生理学\n\n## 课程概述\n研究生物体各系统的功能及其调节：以人和动物生理为主干的整合性课程。\n\n## 主要内容\n- 神经与肌肉生理、感觉系统\n- 循环、呼吸、消化与排泄\n- 内分泌与生殖、体温与内环境稳态\n- 植物生理概要\n\n## 先修与后续\n通向 [[r-tissues-organs]]、[[r-neuro]]；与医学（[[r-medphy]] 相关应用）衔接。",
