   "body": "# 无机化学\n\n## 课程概述\n研究元素及其无机化合物的组成、结构、性质与反应：配位化学是其理论核心。\n\n## 主要内容\n- 酸碱理论与非水溶剂、配位化学（晶体场/配位场理论）\n- 主族元素化学分区讨论\n- 过渡金属与稀土元素化学、无机固体化学初步\n\n## 先修与后续\n通向 [[r-inorganic-res]]；与材料、催化（[[r-materials-chem]]、[[r-physchem-res]]）衔接。",
