   "body": "# 仪器分析\n\n## 课程概述\n基于物理仪器的现代分析方法：光谱、色谱、质谱与电化学分析的仪器原理与应用。\n\n## 主要内容\n- 紫外-可见/红外/原子吸收与发射光谱\n- 气相/液相色谱、毛细管电泳\n- 质谱、核磁共振波谱初步、电化学分析\n\n## 先修与后续\n通向 [[r-analytical-res]]；谱学物理原理对应 [[r-spectroscopy]]。",
