   "body": "# 物理化学\n\n## 课程概述\n化学的理论主干：用物理学原理定量描述化学体系——热力学、动力学、电化学与界面胶体。\n\n## 主要内容\n- 热力学三定律、化学势与相平衡\n- 化学动力学：速率理论、链反应、催化\n- 电化学：电极电势、电解与电池\n- 界面现象与胶体化学\n\n## 先修与后续\n通向 [[c-struct-chem]]、[[c-polymer-chem]] 与 [[r-physchem-res]]。",
