   "body": "# 高分子化学\n\n## 课程概述\n研究大分子的合成、结构与性能：聚合反应机理与高分子链统计。\n\n## 主要内容\n- 逐步聚合与链式聚合（自由基/离子/配位）\n- 共聚合、聚合物化学反应\n- 高分子链构象、聚集态结构与性能初步\n\n## 先修与后续\n通向 [[r-polymer-res]]；与软物质物理（[[r-soft]]）紧密交叉。",
