   "body": "# 结构化学\n\n## 课程概述\n从量子力学出发理解原子与分子的结构：轨道理论、分子对称性与晶体结构。\n\n## 主要内容\n- 氢原子与多电子原子的量子力学处理\n- 分子轨道理论、价键理论、配位场理论\n- 分子对称性与点群、晶体学基础（点阵与空间群）\n\n## 先修与后续\n通向 [[r-quantum-chem]]、[[r-physchem-res]]；群论语言见 [[c-group-theory]]。",
