   "body": "# 人工智能导论\n\n## 课程概述\nAI 的全景导论：从符号主义的搜索与推理到统计学习的基本范式。\n\n## 主要内容\n- 搜索（A*、对抗搜索）与约束满足\n- 知识表示与逻辑推理\n- 概率图模型初步\n- 机器学习与智能体概览\n\n## 先修与后续\n通向 [[c-ml]] 与 [[r-ai-reasoning]]。",
