   "body": "# 算法设计与分析\n\n## 课程概述\n系统化的算法方法论：分治、动态规划、贪心与 NP 完全性。\n\n## 主要内容\n- 渐近分析与递推式\n- 分治、动态规划、贪心\n- 图算法（最短路、匹配、网络流）\n- NP 完全性与近似/随机算法初步\n\n## 先修与后续\n通向 [[r-algorithms]]，是 CS 研究与大厂面试的共同核心。",
