   "body": "# 计算机组成原理\n\n## 课程概述\n从逻辑门到处理器：理解程序如何在真实硬件上运行。\n\n## 主要内容\n- 数的机器表示与运算器\n- 指令系统、数据通路与控制器\n- 存储层次（cache、虚拟存储）\n- 总线、I/O 与流水线初步\n\n## 先修与后续\n通向 [[c-os]] 与 [[r-os-systems]]。",
