   "body": "# 数据结构\n\n## 课程概述\n研究数据的组织方式及其操作效率：表、树、图与散列是全部软件系统的骨架。\n\n## 主要内容\n- 线性表、栈与队列\n- 树与二叉树、堆、平衡树\n- 图结构与遍历、散列表\n- 排序与查找、复杂度分析初步\n\n## 先修与后续\n通向 [[c-algorithms]]、[[c-os]]、[[c-database]]、[[c-compilers]]。",
