   "body": "# 离散数学\n\n## 课程概述\n计算机科学的数学基础：逻辑、集合、关系、图论与初等数论，支撑算法与形式化方法。\n\n## 主要内容\n- 命题逻辑与谓词逻辑\n- 集合、关系与函数\n- 图论基础、树\n- 初等数论与组合计数\n\n## 先修与后续\n通向 [[c-algorithms]]、[[c-compilers]]、[[r-formal-methods]]。",
