   "size": 88,
   "degree": 7,
   "pos": null,
   "fixed": false,
   "body": "# 机器学习\n\n## 课程概述\n数据驱动的学习范式：从线性模型到深度网络，经验风险最小化是统一视角。\n\n## 主要内容\n- 监督学习：线性模型、SVM、树与集成\n- 神经网络与反向传播、深度学习初步\n- 无监督学习：聚类、降维\n- 泛化理论、正则化与模型评估\n\n## 先修与后续\n通向 [[r-ml-res]]、[[r-cv]]、[[r-nlp]]、[[r-robotics]]。",
