   "body": "# 操作系统\n\n## 课程概述\n研究管理硬件资源、抽象执行环境的系统软件：进程、内存、文件与设备。\n\n## 主要内容\n- 进程与线程、调度、同步与死锁\n- 内存管理与虚拟存储\n- 文件系统、设备管理\n- 安全与虚拟化初步\n\n## 先修与后续\n通向 [[c-networks-course]]（网络栈）与 [[r-os-systems]]。",
