   "body": "# 程序设计基础\n\n## 课程概述\n计算机科学的第一课：用一门语言（C/C++/Python）学会把问题变成程序，建立计算思维。\n\n## 主要内容\n- 基本语法、数据类型与控制结构\n- 函数、数组、指针/引用与内存初步\n- 结构化程序设计、调试与测试\n- 简单算法与复杂度直觉\n\n## 先修与后续\n一切 CS 课程的前置：[[c-data-structures]]、[[c-computer-arch]] 等。",
