   "body": "# 计算物理进阶\n\n## 课程概述\n面向研究的大规模数值模拟与现代计算方法（本研衔接）。\n\n## 主要内容\n- 偏微分方程的高性能求解、并行计算\n- 蒙特卡洛与分子动力学进阶\n- 机器学习在物理问题中的应用\n\n## 先修与后续\n先修 [[c-computational]]。支撑 [[r-materials]]、[[r-lattice]]、[[r-numerical-rel]] 等计算密集型方向。",
