   "body": "# 电路原理\n\n## 课程概述\n电类工程的入门课：集总电路的基本定律与分析方法。\n\n## 主要内容\n- 基尔霍夫定律、等效变换与网络定理\n- 一阶/二阶动态电路时域分析\n- 正弦稳态分析与相量法、三相电路\n- 二端口网络\n\n## 先修与后续\n通向 [[c-electronics]] 与 [[r-electrical-eng]]。",
