   "body": "# 自动控制原理\n\n## 课程概述\n研究动态系统的反馈控制：经典控制（频域）与现代控制（状态空间）。\n\n## 主要内容\n- 传递函数与方框图、时域分析\n- 根轨迹与频域稳定判据（奈奎斯特/波特）\n- PID 与校正设计\n- 状态空间、能控能观与极点配置\n\n## 先修与后续\n通向 [[r-control]] 与 [[r-robotics]]。",
