   "body": "# 工程力学\n\n## 课程概述\n面向工程的力学：静力学与材料力学（杆件的强度、刚度与稳定性）。\n\n## 主要内容\n- 静力学：力系简化与平衡\n- 材料力学：拉压弯扭的应力与变形\n- 强度理论、压杆稳定\n- 疲劳与断裂初步\n\n## 先修与后续\n通向 [[r-mechanical-eng]]、[[r-civil-env-eng]]、[[r-aerospace]]。",
