   "fixed": false,
   "body": "# 工程热力学\n\n## 课程概述\n能量转换的工程科学：热机、制冷与动力循环的效率分析。\n\n## 主要内容\n- 热力学定律的工程表述、㶲分析\n- 气体与蒸汽动力循环（朗肯、布雷顿）\n- 制冷循环与热泵\n- 传热学初步（导热/对流/辐射）\n\n## 先修与后续\n通向 [[r-energy-eng]]；与 [[r-energy-env-chem]] 在能源转化上衔接。",
