   "body": "# 材料科学基础\n\n## 课程概述\n材料的成分-结构-工艺-性能四面体：工程材料的共同语言。\n\n## 主要内容\n- 晶体结构与缺陷（位错）\n- 相图与相变、扩散\n- 金属/陶瓷/高分子的性能与加工\n- 材料表征方法初步\n\n## 先修与后续\n通向 [[r-materials-eng]]；与 [[r-materials]]、[[r-materials-chem]] 构成材料研究的三个侧面。",
