   "fixed": false,
   "body": "# 电磁学\n\n## 课程概述\n系统建立电磁场的实验定律与麦克斯韦方程组的积分形式，是电动力学的唯象基础。\n\n## 主要内容\n- 静电场、导体与电介质、稳恒电流与电路\n- 稳恒磁场、磁介质、电磁感应\n- 麦克斯韦方程组（积分形式）与电磁波概念\n\n## 先修与后续\n先修 [[c-mechanics]]。后续为 [[c-optics]]（光是电磁波）与 [[c-electrodynamics]]（系统的场论表述）。",
