   "body": "# 通信原理\n\n## 课程概述\n研究信息可靠传输的基本原理：调制解调、信道与最佳接收。\n\n## 主要内容\n- 模拟与数字调制（AM/FM、ASK/PSK/QAM）\n- 信源与信道模型、噪声中的最佳接收\n- 信道编码初步（分组码、卷积码）\n- 同步与复用\n\n## 先修与后续\n通向 [[r-comm-systems]]；理论上限由 [[c-info-theory-course]] 给出。",
