   "body": "# 数字信号处理\n\n## 课程概述\n研究离散时间信号的数字处理算法：滤波器设计与快速变换是两大支柱。\n\n## 主要内容\n- 离散傅里叶变换与 FFT\n- 数字滤波器设计（FIR/IIR）\n- 多采样率处理与小波初步\n- 谱估计初步\n\n## 先修与后续\n通向 [[c-image-processing]] 与 [[r-signal-processing]]。",
