   "fixed": false,
   "body": "# 数字图像处理\n\n## 课程概述\n研究图像的数字化处理：增强、复原、分割与压缩，是计算机视觉的经典底层。\n\n## 主要内容\n- 空域增强（直方图、滤波）与频域处理\n- 图像复原（去噪、去模糊）与重建\n- 边缘检测、分割与形态学\n- 图像压缩标准（JPEG）初步\n\n## 先修与后续\n通向 [[r-image-speech]]；与学习驱动的 [[r-cv]] 衔接。",
