   "degree": 6,
   "pos": null,
   "fixed": false,
   "body": "# 信号与系统\n\n## 课程概述\n信息与电子类专业的核心基础课：用变换方法统一描述信号与线性时不变系统。\n\n## 主要内容\n- 连续/离散信号与 LTI 系统、卷积\n- 傅里叶级数与傅里叶变换、频谱分析\n- 拉普拉斯变换与 z 变换、系统函数\n- 采样定理\n\n## 先修与后续\n通向 [[c-dsp]]、[[c-comm-principles]]、[[c-control-principles]]。",
