   "fixed": false,
   "body": "# 解析几何\n\n## 课程概述\n用坐标与代数方法研究几何：向量代数、空间曲面曲线与二次曲面分类，是几何思维的入门。\n\n## 主要内容\n- 向量代数与坐标变换\n- 空间直线、平面、曲面与曲线\n- 二次曲线与二次曲面的分类\n\n## 先修与后续\n为 [[c-differential-geometry]] 与 [[c-math-analysis]] 的多元部分提供几何直观。",
