   "body": "# 复变函数\n\n## 课程概述\n研究复变量解析函数：柯西积分理论、留数与保形映射，以简洁深刻著称。\n\n## 主要内容\n- 解析函数与柯西-黎曼方程、复积分\n- 柯西积分公式、泰勒与洛朗展开、留数定理\n- 保形映射、解析延拓初步\n\n## 先修与后续\n通向 [[r-analysis]]；在物理中用于积分计算、色散关系与二维场论。",
