   "body": "# 微分几何\n\n## 课程概述\n用微积分研究曲线、曲面与流形：从古典曲面论到黎曼几何。\n\n## 主要内容\n- 曲线论与曲面论：曲率、第一/第二基本形式\n- 高斯绝妙定理、测地线\n- 流形、切丛与黎曼度量初步\n\n## 先修与后续\n通向 [[r-geometry-topology]] 与 [[r-mathematical-physics]]；物理上支撑 [[c-gr]]。",
