   "body": "# 泛函分析\n\n## 课程概述\n研究无穷维线性空间上的算子：巴拿赫空间、希尔伯特空间与算子理论。\n\n## 主要内容\n- 赋范空间与巴拿赫空间、三大基本原理\n- 希尔伯特空间几何、正交投影\n- 有界线性算子与谱理论初步\n\n## 先修与后续\n通向 [[r-analysis]]、[[r-pde-research]]、[[r-mathematical-physics]]。",
