   "body": "# 数值分析\n\n## 课程概述\n研究连续数学问题的离散近似算法：误差、收敛性与稳定性分析。\n\n## 主要内容\n- 插值与逼近、数值积分与微分\n- 线性方程组直接法与迭代法、特征值计算\n- 非线性方程求根、常微分方程数值解\n\n## 先修与后续\n通向 [[r-scientific-computing]]，支撑一切计算密集型研究。",
