   "body": "# 分子网络与组学\n\n## 方向概述\narXiv: q-bio.MN。把细胞看作网络：基因调控、信号转导、代谢与多组学整合。\n\n## 核心问题\n- 基因调控网络与网络模体\n- 蛋白质组/代谢组的定量图谱\n- 多组学整合与细胞状态建模（虚拟细胞）\n\n## 代表方法与设施\n高通量组学技术 + 网络推断与动力系统建模；系统生物学的核心路径。",
