   "body": "# 亚细胞过程\n\n## 方向概述\narXiv: q-bio.SC。研究细胞内部的组织与运转：细胞器组装、分子马达与物质定向运输。\n\n## 核心问题\n- 细胞骨架动力学与细胞分裂\n- 分子马达与囊泡运输\n- 细胞器发生、定位与质量控制\n\n## 代表方法与设施\n活细胞超分辨成像、光遗传操控与体外重组体系。",
