   "body": "# 神经科学与认知\n\n## 方向概述\narXiv: q-bio.NC。研究神经系统的信息处理：从离子通道到认知与行为。\n\n## 核心问题\n- 神经元与突触的电生理和动力学\n- 神经环路的连接组与功能成像\n- 感觉-运动控制、学习记忆与意识的神经基础\n- 类脑计算接口\n\n## 代表方法与设施\n膜片钳、双光子成像、连接组学与计算建模；与人工智能双向启发。",
