   "body": "# 种群、进化与生态\n\n## 方向概述\narXiv: q-bio.PE。研究种群动态、物种形成与协同演化：从分子进化到食物网与传染病动力学。\n\n## 核心问题\n- 分子进化与系统发育、定向演化\n- 种群动态与空间模型、流行病传播（SIR 及其扩展）\n- 生物多样性的形成与维持、生命起源\n\n## 代表方法与设施\n野外长期观测 + 基因组数据 + 数学模型；与统计物理（[[r-complex]]）共享工具。",
