   "body": "# 合成生物学与生物工程\n\n## 方向概述\n以工程化思维设计与重建生命系统：基因回路、合成基因组与细胞工厂。\n\n## 核心问题\n- 基因回路与逻辑门设计\n- 合成基因组与底盘细胞、基因组编辑（CRISPR）\n- 代谢工程与细胞工厂、无细胞体系\n\n## 代表方法与设施\n设计-构建-测试-学习（DBTL）循环；通向生物制造与基因治疗。",
