   "body": "# 组织、器官与生理系统\n\n## 方向概述\narXiv: q-bio.TO。研究组织与器官层面的功能与力学：血流、生物力学、电活动与肿瘤生长。\n\n## 核心问题\n- 心血管与血流的生物力学\n- 组织形态发生的力-化学耦合\n- 肿瘤生长的多尺度模型、器官芯片\n\n## 代表方法与设施\n类器官与器官芯片、医学影像与计算建模结合。",
