   "body": "# 化学生物学\n\n## 方向概述\nGB/T 13745: 15060。用化学工具干预与解析生命过程：小分子探针、蛋白修饰与药物发现。\n\n## 核心问题\n- 活性小分子探针与靶点发现\n- 蛋白质化学修饰与非天然氨基酸\n- 核酸化学、生物正交反应与活体标记\n\n## 代表方法与设施\n位于化学与生命科学的界面：上游是 [[r-organic-res]]，下游通向 [[r-biomolecules]] 与药物化学。",
