   "body": "# 材料化学\n\n## 方向概述\nGB/T 13745: 15065。以化学合成创制功能材料：能源材料、纳米材料与低维材料。\n\n## 核心问题\n- 电池与催化材料（锂电、固态电解质、光催化）\n- 低维材料：二维材料、量子点、钙钛矿\n- 纳米化学合成与表界面调控\n\n## 代表方法与设施\n材料基因组与高通量筛选；与凝聚态物理的 [[r-materials]]共享研究对象。",
