   "fixed": false,
   "body": "# 分析化学研究\n\n## 方向概述\n教育部二级学科 070302。发展更快、更灵敏、更小尺度的测量方法：从单分子检测到活体成像。\n\n## 核心问题\n- 质谱新技术（组学分析、单细胞质谱）\n- 光谱与成像：拉曼、荧光超分辨联用\n- 微流控芯片与生物传感器、化学计量学\n\n## 代表方法与设施\n大科学装置（同步辐射、自由电子激光）联用；服务环境、生命与材料科学。",
