   "fixed": false,
   "body": "# 半导体物理\n\n## 方向概述\n研究半导体的载流子行为与器件物理，是微电子与光电子的科学基础。\n\n## 核心问题\n- 载流子统计与输运、p-n 结\n- 低维与宽禁带半导体\n- 半导体光电子器件（激光器、探测器）\n\n## 代表方法与设施\n外延生长（MBE）、器件制备与电学/光学表征。\n\n## 与其他方向的联系\n与 [[r-meso]]、[[r-materials]]、[[r-laser]]（半导体激光器）交叉。",
