   "fixed": false,
   "body": "# 磁学与自旋电子学\n\n## 方向概述\n研究磁有序与自旋自由度在信息器件中的应用。\n\n## 核心问题\n- 磁有序与磁激发（自旋波、斯格明子）\n- 自旋输运：自旋霍尔效应、自旋矩转移\n- 磁性存储与自旋器件\n\n## 代表方法与设施\n磁光测量、铁磁共振、微磁模拟。\n\n## 与其他方向的联系\n与 [[r-strong-corr]]、[[r-meso]] 交叉。",
