   "body": "# 计算机图形学与人机交互\n\n## 方向概述\narXiv: cs.GR / cs.HC。研究图像的合成与人的计算交互：渲染、几何处理与交互界面。\n\n## 核心问题\n- 实时渲染与光线追踪、神经渲染\n- 几何处理与动画仿真\n- 交互范式、可用性与普适计算\n- 数据可视化\n\n## 代表方法与设施\nGPU 编程与感知实验；SIGGRAPH/CHI 社区，与 [[r-cv]] 在三维重建上合流。",
