   "body": "# 机器人学\n\n## 方向概述\narXiv: cs.RO。研究感知-决策-行动的物理闭环：操作、移动与人形机器人。\n\n## 核心问题\n- 运动规划与全身控制\n- 操作学习与灵巧手（模仿/强化学习）\n- 视觉-语言-动作模型（VLA）与具身大模型\n- Sim2Real 与硬件本体\n\n## 代表方法与设施\n硬件平台 + 大规模仿真 + 真实数据飞轮；RSS/ICRA/CoRL 社区。",
