   "body": "# 程序语言与形式方法\n\n## 方向概述\narXiv: cs.PL / cs.FL / cs.LO。研究编程语言的设计、语义与程序正确性的数学证明。\n\n## 核心问题\n- 类型系统与类型论、语言语义\n- 模型检测与定理证明（Coq/Lean）\n- 程序分析与验证、自动化推理（SMT）\n\n## 代表方法与设施\n高可信软件（航天、密码协议）的基石；AI 数学证明（Lean）是新热点。",
