   "body": "# 海洋物理\n\n## 方向概述\n研究海洋中的运动：环流、波动与混合。\n\n## 核心问题\n- 大洋环流与温盐环流\n- 海洋内波与湍流混合\n- 海气相互作用\n\n## 代表方法与设施\n潜标与浮标阵（Argo）、海洋模式。\n\n## 与其他方向的联系\n与 [[r-atmos]]、[[r-fluid-dyn]] 交叉。",
