   "body": "# 航空宇航科学与技术\n\n## 方向概述\n教育部 0825。研究飞行器的设计、推进与制导控制。\n\n## 核心问题\n- 空气动力学：高超声速与气动布局\n- 航空发动机与火箭推进\n- 飞行器制导导航与控制（GNC）\n- 航天器总体设计与深空探测\n\n## 代表方法与设施\n风洞/试车台/飞行试验 + 多学科设计优化（MDO）；国家重大工程牵引。",
