   "body": "# 土木与环境工程\n\n## 方向概述\n教育部 0814 / 0830。研究建筑、桥梁、基础设施与水/土/气环境治理。\n\n## 核心问题\n- 结构工程：抗震、抗风与韧性城市\n- 岩土与地下工程、智能建造\n- 水处理与资源化、大气污染控制\n- 固废处置与土壤修复\n\n## 代表方法与设施\n大型结构试验、环境过程模拟与工程标准体系；与 [[r-energy-env-chem]] 在污染治理上交叉。",
