   "body": "# 能源与动力工程\n\n## 方向概述\n教育部 0807（动力工程及工程热物理）。研究能量高效清洁转换的装备与系统。\n\n## 核心问题\n- 燃气轮机与航空发动机热端技术\n- 高效低污染燃烧与新型动力循环（超临界 CO₂）\n- 储能系统与综合能源系统\n- 核能热工水力与反应堆热工\n\n## 代表方法与设施\n实验台架 + CFD + 系统集成；能源安全与\"双碳\"的核心工科。",
