   "body": "# 控制科学与工程\n\n## 方向概述\n教育部 0811。研究动态系统的建模、估计与控制：从经典反馈到智能自主系统。\n\n## 核心问题\n- 鲁棒与最优控制（H∞、MPC）\n- 非线性与混杂系统控制\n- 多智能体协同与无人系统\n- 学习与控制融合（数据驱动控制）\n\n## 代表方法与设施\n李雅普诺夫方法、频域/状态空间工具；eess.SY；支撑工业自动化与 [[r-robotics]]。",
