   "body": "# 电气工程\n\n## 方向概述\n教育部 0808。研究电能的生产、传输、变换与利用。\n\n## 核心问题\n- 新型电力系统：新能源并网与稳定分析\n- 电力电子变换器与宽禁带器件（SiC/GaN）\n- 电机与电气传动\n- 超导电工与脉冲功率（[[r-mcf]] 的电源支撑）\n\n## 代表方法与设施\n电磁场-电路耦合建模与大电网仿真；\"双碳\"目标下的主干学科。",
