   "body": "# 机械工程\n\n## 方向概述\n教育部 0802。研究机械系统的设计、制造与运行。\n\n## 核心问题\n- 机构学与机器人机构（与 [[r-robotics]] 交叉）\n- 精密/超精密加工与增材制造\n- 摩擦学、振动与故障诊断\n- 微纳机电系统（MEMS）\n\n## 代表方法与设施\nCAD/CAE/CAM 数字化链条 + 实验力学；高端装备的国家战略方向。",
