   "body": "# 非线性动力学与混沌\n\n## 方向概述\narXiv: nlin.CD。研究确定性系统中的分岔、混沌与复杂时间行为。\n\n## 核心问题\n- 分岔理论、奇怪吸引子\n- 混沌的控制与同步\n- 时间序列分析与复杂网络动力学\n\n## 代表方法与设施\n动力系统理论、数值分岔分析。\n\n## 与其他方向的联系\n与 [[r-turbulence]]、[[r-pattern]]、[[r-complex]] 交叉。",
