   "body": "# 图案形成\n\n## 方向概述\narXiv: nlin.PS。研究远离平衡系统中自发形成的空间结构：斑图、孤波与耗散结构。\n\n## 核心问题\n- 反应-扩散系统与图灵斑图\n- 孤波与可积系统\n- 界面生长与枝晶\n\n## 代表方法与设施\n振幅方程、数值模拟、对流实验。\n\n## 与其他方向的联系\n与 [[r-nonlinear]]、[[r-soft]] 交叉。",
