   "body": "# 湍流\n\n## 方向概述\n经典物理最著名的未解问题：多尺度强非线性运动的统计规律。\n\n## 核心问题\n- 能级串与惯性区标度律\n- 间歇性与相干结构\n- 湍流封闭模型与机器学习建模\n\n## 代表方法与设施\n超算直接数值模拟、高雷诺数实验。\n\n## 与其他方向的联系\n与 [[r-nonlinear]]、[[r-atmos]]、[[r-space-plasma]]（等离子体湍流）交叉。",
