   "body": "# 黑洞物理\n\n## 方向概述\n研究黑洞的解、热力学与观测：从史瓦西几何到事件视界成像。\n\n## 核心问题\n- 黑洞解与扰动、准正规模\n- 黑洞热力学与霍金辐射、信息佯谬\n- 阴影成像与强场检验\n\n## 代表方法与设施\n事件视界望远镜（EHT）、引力波观测、半经典与全息方法。\n\n## 与其他方向的联系\n与 [[r-he-astro]]、[[r-qg]]、[[r-grav-wave]] 交叉。",
