   "body": "# 数值相对论\n\n## 方向概述\n在计算机上求解强场、动态时空的爱因斯坦方程。\n\n## 核心问题\n- 3+1 分解与演化格式（BSSN 等）\n- 双黑洞/双中子星并合模拟\n- 引力波模板与临界现象\n\n## 代表方法与设施\n高性能计算集群、开源码（Einstein Toolkit）。\n\n## 与其他方向的联系\n直接服务 [[r-grav-wave]]；与 [[r-he-astro]]（并合电磁对应体）交叉。",
