   "body": "# 图像、语音与媒体处理\n\n## 方向概述\narXiv: eess.IV / eess.AS。研究图像、语音与音视频媒体的采集、处理与传输。\n\n## 核心问题\n- 医学影像重建与分析（CT/MRI/超声）\n- 语音识别、合成与音频理解\n- 视频编码与流媒体（H.266/AV1）\n- 计算成像与新型传感器\n\n## 代表方法与设施\n信号处理经典方法与深度学习混合；与临床、广电产业紧密联动。",
