   "body": "# 微电子与集成电路\n\n## 方向概述\n教育部 0809 电子科学与技术方向之一。研究芯片的器件、设计与制造。\n\n## 核心问题\n- 先进制程器件（FinFET/GAA）与新型存储\n- 模拟/射频/数字集成电路设计\n- EDA 工具与设计自动化\n- 先进封装与芯粒（Chiplet）\n\n## 代表方法与设施\n工艺线 + EDA 软件 + 架构设计的重资产协同；算力时代的物理底座。",
