   "body": "# 信号与信息处理\n\n## 方向概述\narXiv: eess.SP。研究从信号中提取信息的理论与算法：估计、滤波与稀疏恢复。\n\n## 核心问题\n- 统计信号处理：检测、估计与自适应滤波\n- 稀疏表示与压缩感知\n- 阵列信号处理与雷达/声呐\n- 机器学习与信号处理的融合\n\n## 代表方法与设施\n优化理论与统计推断；是雷达、通信与医学成像的算法内核。",
