   "fixed": false,
   "body": "# 信息论与编码\n\n## 方向概述\narXiv: math.IT。香农开创的信息量化理论：信道容量、信源编码与纠错码。\n\n## 核心问题\n- 熵、互信息与信道容量定理\n- 纠错码（LDPC、极化码）\n- 率失真理论与网络信息论\n\n## 代表方法与设施\n现代通信（5G 极化码）与密码学的理论基础。",
