   "body": "# 数学物理\n\n## 方向概述\narXiv: math.MP。用严格数学研究物理理论：量子力学、统计力学与场论的数学基础。\n\n## 核心问题\n- 量子力学的算子理论表述\n- 统计力学的严格结果（相变存在性）\n- 可积系统与公理化/构造性量子场论\n\n## 代表方法与设施\n泛函分析、表示论与概率论的交叉地带。",
