   "body": "# 最优化与运筹控制\n\n## 方向概述\narXiv: math.OC。研究约束下的最优决策：凸优化、最优控制与博弈论。\n\n## 核心问题\n- 线性规划与凸优化（内点法、一阶算法）\n- 最优控制（庞特里亚金极大值原理）\n- 博弈论与均衡计算\n\n## 代表方法与设施\n机器学习训练、运筹调度与工程控制的数学引擎。",
