   "body": "# 概率论与随机过程\n\n## 方向概述\narXiv: math.PR。测度论框架下研究随机现象：极限定理、随机过程与随机矩阵。\n\n## 核心问题\n- 大数定律、中心极限定理与大偏差\n- 马尔可夫过程、鞅、布朗运动与随机微分方程\n- 随机矩阵、渗流与相互作用粒子系统\n\n## 代表方法与设施\n为金融数学、统计物理与机器学习理论提供工具。",
