   "body": "# 统计学\n\n## 方向概述\narXiv: math.ST。从数据中推断规律：参数估计、假设检验、回归与高维统计。\n\n## 核心问题\n- 估计理论（极大似然、贝叶斯）与假设检验\n- 回归分析、时间序列与实验设计\n- 高维统计、统计学习与 MCMC 计算\n\n## 代表方法与设施\n支撑实验物理（[[r-hep-ex]] 的显著性分析）、生物信息与数据科学。",
