   "body": "# 代数几何\n\n## 方向概述\narXiv: math.AG。研究多项式方程组的解集（代数簇）：概形理论是现代标准语言。\n\n## 核心问题\n- 代数簇的分类、双有理几何\n- 层上同调、黎曼-罗赫定理\n- 模空间与枚举几何\n\n## 代表方法与设施\n概形与导出范畴；与数论（算术几何）、弦论（镜像对称，[[r-hep-th]] 相关）交叉。",
