   "body": "# 动力系统\n\n## 方向概述\narXiv: math.DS。研究映射与流随时间的渐近行为：混沌、遍历性与分形几何。\n\n## 核心问题\n- 混沌与奇异吸引子、符号动力学\n- 遍历定理、熵与混合性\n- 复动力系统（朱利亚集、芒德博集）\n\n## 代表方法与设施\n拓扑与共轭方法、测度论；与统计物理（[[c-statistical-mechanics]]）的遍历假设呼应。",
