   "body": "# 激光等离子体\n\n## 方向概述\n研究强激光与等离子体相互作用及其加速与辐射应用。\n\n## 核心问题\n- 激光尾场加速电子/离子\n- 快点火与冲击点火\n- 实验室天体物理（喷流、激波类比）\n\n## 代表方法与设施\n拍瓦激光装置、粒子与辐射诊断。\n\n## 与其他方向的联系\n与 [[r-laser]]、[[r-icf]]、[[r-he-astro]] 交叉。",
