   "body": "# 量子通信\n\n## 方向概述\n利用量子态传输信息：量子密钥分发与量子网络。\n\n## 核心问题\n- 量子密钥分发（QKD）协议与安全性\n- 量子中继与量子存储\n- 星地量子通信与量子互联网\n\n## 代表方法与设施\n光纤与自由空间链路、墨子号卫星。\n\n## 与其他方向的联系\n与 [[r-qc]]、[[r-qmetro]]（单光子探测）交叉。",
